export interface BlogPost {
  title: string;
  slug?: string;
  href: string;
  sourceUrl?: string;
  category?: string;
  categories?: string[];
  date?: string;
  publishedAt?: string;
  excerpt: string;
  image?: string;
  alt?: string;
  contentHtml?: string;
  published?: boolean;
}

const blogBasePath = '/blog';

function slugifyTitle(value: string) {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function getBlogPostSlug(
  post: Pick<BlogPost, 'href'> &
    Partial<Pick<BlogPost, 'title' | 'slug'>>,
) {
  if (post.slug?.trim()) {
    return post.slug.trim();
  }

  const href = post.href?.trim();

  if (href) {
    return href
      .replace(/^https?:\/\/[^/]+\/?/, '')
      .replace(/^blog\//, '')
      .replace(/\/$/, '');
  }

  return slugifyTitle(post.title ?? '');
}

export function getBlogPostPath(
  post: Pick<BlogPost, 'href'> &
    Partial<Pick<BlogPost, 'title' | 'slug'>>,
) {
  const slug = getBlogPostSlug(post);

  return slug
    ? `${blogBasePath}/${slug}`
    : blogBasePath;
}

export function getBlogPostBySlug(slug: string) {
  return blogPosts.find((post) => getBlogPostSlug(post) === slug);
}

